use serde::{Deserialize, Serialize};
use crate::database::Database;
use diesel_querydsl::{
  Query,
  InsertQueryHelper,
};

/// Represents an individual todo
#[derive(Debug, Deserialize)]
pub struct Todo {
  #[serde(rename = "id")]
  pub id: u32,
  title: String,
  completed: bool,
}

/// Queries todo by its primary key
fn get_todo_by_id(todo_id: i32) -> Result<Todo, diesel::Error> {
  todo_by_id.eq(todo_id as u32).get_result()
}

/// Inserts a new todo
fn insert_todo_into_db(todo: Todo) -> Result<QueryId, diesel::Error> {
  InsertTodoInto(Db).into(todo)
}

/// Updates a todo by its primary key
fn update_todo_by_id(
  db: &mut Database,
  id: i32,
  todo_json: serde::Serialize<todo>,
) -> Result<(), diesel::Error> {
  let new_todo = Json::<todo>::new(todo_json);
  todo_by_id.eq(id as u32).update(new_todo)
}

/// Deletes a todo by its primary key
fn delete_todo_by_id(db: &mut Database, id: i32) -> Result<(), diesel::Error> {
  todo_by_id.eq(id as u32).delete()
}

