require 'rails_helper'

RSpec.describe Todo, type: :model do
  it { should validate_presence_of(:title) }
end

RSpec.describe TodosController, type: :request do
  describe 'GET /todos/:id' do
    let(:todo) { create(:todo, title: 'Sample Todo', completed: true) }
    it 'returns the todo with specified id' do
      get "/todos/#{todo.id}"
      expect(response).to have_http_status(:ok)
      expect(JSON.parse(response.body)).to eq({
        id: todo.id,
        title: 'Sample Todo',
        completed: true
      })
    end
  end

  describe 'POST /todos' do
    let(:params) { { title: 'New Todo', completed: false } }
    it 'creates a new todo and returns the created todo' do
      expect {
        post "/todos", params: params
        last_response.status
      }.to eq([201, "Created"])

      expect {
        get "/todos/#{Todo.last.id}"
        JSON.parse(last_response.body)
      }.to eq(
        id: Todo.last.id,
        title: 'New Todo',
        completed: false
      )
    end

    it "returns 400 when no params are supplied" do
      expect {
        post "/todos"
        last_response.status
      }.to eq([400])
    end

    it "returns 404 when the todo id is not found" do
      expect {
        get "/todos/1234567890"
        last_response.status
      }.to eq([404])
    end
  end

  describe 'PUT /todos/:id' do
    let(:todo) { create(:todo, title: 'Original Title', completed: false) }
    let(:params) { { title: 'Updated Title' } }

    it 'updates the todo with specified id and returns the updated todo' do
      expect {
        put "/todos/#{todo.id}", params: params
        last_response.status
      }.to eq([200])

      expect {
        get "/todos/#{todo.id}"
        JSON.parse(last_response.body)
      }.to eq(
        id: todo.id,
        title: 'Updated Title',
        completed: false
      )
    end

    it "returns 400 when no params are supplied" do
      expect {
        put "/todos/#{todo.id}"
        last_response.status
      }.to eq([400])
    end

    it "returns 404 when the todo id is not found" do
      expect {
        put "/todos/1234567890"
        last_response.status
      }.to eq([404])
    end
  end

  describe 'DELETE /todos/:id' do
    let(:todo) { create(:todo, title: 'Todo to Delete', completed: false) }
    it 'deletes the todo with specified id and returns a success message' do
      expect {
        delete "/todos/#{todo.id}"
        last_response.status
      }.to eq([200])

      expect {
        get "/todos/#{todo.id}"
        last_response.status
      }.to eq([404])
    end

    it "returns 404 when the todo id is not found" do
      expect {
        delete "/todos/1234567890"
        last_response.status
      }.to eq([404])
    end
  end
end

