import { Todo } from '../models/todo.model';

// In-memory storage for todos (in a real app, this would be a database)
let todos: Todo[] = [];

// List all todos
export const listTodos = async (): Promise<Todo[]> => {
  return todos;
};

// Get todo by id
export const getTodoById = async (id: string): Promise<Todo | null> => {
  const todo = todos.find((todo) => todo.id === id);
  return todo || null;
};

// Create a new todo
export const createTodo = async (todoData: Omit<Todo, 'id'>): Promise<Todo> => {
  const todo: Todo = {
    id: Date.now().toString(),
    ...todoData,
  };
  todos.push(todo);
  return todo;
};

// Update todo by id (only fields provided in request body)
export const updateTodo = async (id: string, updateData: Partial<Todo>): Promise<Todo | null> => {
  const todoIndex = todos.findIndex((todo) => todo.id === id);
  if (todoIndex === -1) {
    return null;
  }

  const todo = todos[todoIndex];
  todos[todoIndex] = { ...todo, ...updateData };

  return todos[todoIndex];
};

// Delete todo by id
export const deleteTodo = async (id: string): Promise<boolean> => {
  const index = todos.findIndex((todo) => todo.id === id);
  if (index === -1) {
    return false;
  }

  todos.splice(index, 1);
  return true;
};

