use actix_web::{web, HttpResponse, HttpRequest, http::header::HeaderValue};
use serde::{Deserialize, Serialize};
use std::sync::Arc;
use std::collections::HashMap;

#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct Todo {
    pub id: i32,
    pub title: String,
    pub completed: bool,
}

#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct TodoList {
    pub todos: Vec<Todo>,
}

// Global state (in a real app, this would be a database)
lazy_static::lazy_static! {
    static ref TODOS: Arc<mut HashMap<i32, Todo>> = Arc::new(HashMap::new());
}

// GET /todos - list all todos
async fn list_todos() -> HttpResponse {
    let todos = TODOS
        .lock()
        .clone()
        .into_iter()
        .map(|(id, todo)| todo)
        .collect::<Vec<Todo>>();
    HttpResponse::Ok().json(TodoList { todos })
}

// GET /todos/{id} - get todo by id
async fn get_todo(id: web::Path<i32>) -> HttpResponse {
    let todo = TODOS
        .lock()
        .get(&id)
        .cloned()
        .unwrap_or_else(|| {
            HttpResponse::NotFound().json("Todo not found")
        });
    HttpResponse::Ok().json(todo)
}

// POST /todos - create a new todo
async fn create_todo(
    req: web::Json<Todo>,
) -> HttpResponse {
    let todo = Todo {
        id: req.id,
        title: req.title.clone(),
        completed: req.completed,
    };
    TODOS
        .lock()
        .insert(todo.id, todo);
    HttpResponse::Ok().json(todo)
}

// PUT /todos/{id} - update todo by id (only fields provided in body)
async fn update_todo(
    id: web::Path<i32>,
    req: web::Json<Todo>,
) -> HttpResponse {
    let todo = TODOS
        .lock()
        .get_mut(&id)
        .cloned()
        .unwrap_or_else(|| {
            return HttpResponse::NotFound().json("Todo not found");
        });
    if let Some(title) = req.title.clone() {
        todo.title = title;
    }
    if let Some(completed) = req.completed {
        todo.completed = completed;
    }
    HttpResponse::Ok().json(todo)
}

// DELETE /todos/{id} - delete todo by id
async fn delete_todo(id: web::Path<i32>) -> HttpResponse {
    let todo = TODOS
        .lock()
        .remove(&id);
    if todo.is_none() {
        return HttpResponse::NotFound().json("Todo not found");
    }
    HttpResponse::Ok().json("Todo deleted")
}

// Route definitions
pub fn routes() -> Vec<(String, Box<dyn Fn()>)> {
    vec![
        ("/todos".to_string(), Box::new(list_todos)),
        ("/todos/{id}".to_string(), Box::new(get_todo)),
        ("/todos/{id}".to_string(), Box::new(update_todo)),
        ("/todos/{id}".to_string(), Box::new(delete_todo)),
    ]
}

