use actix_web::{web, HttpResponse, HttpResponseBuilder};
use serde::{Deserialize, Serialize};

#[derive(Serialize, Deserialize, Debug)]
pub struct Todo {
    pub id: i32,
    pub title: String,
    pub completed: bool,
}

// Mock data for demonstration
static mut TODOS: Vec<Todo> = vec![];

impl Todo {
    pub fn new(id: i32, title: String, completed: bool) -> Self {
        Todo { id, title, completed }
    }
}

// GET /todos - list all todos
pub async fn list_todos() -> HttpResponse {
    HttpResponse::Ok().json(&mut unsafe { &mut TODOS })
}

// GET /todos/{id} - get todo by id
pub async fn get_todo(id: web::Path<i32>) -> HttpResponse {
    let todo = unsafe { TODOS.iter().find(|t| t.id == id.into()) };
    match todo {
        Some(todo) => HttpResponse::Ok().json(todo),
        None => HttpResponse::NotFound().json("Todo not found"),
    }
}

// POST /todos - create a new todo
pub async fn create_todo(todo: web::Json<Todo>) -> HttpResponse {
    let new_todo = Todo {
        id: unsafe { TODOS.len() + 1 },
        title: todo.title.clone(),
        completed: todo.completed,
    };
    unsafe { TODOS.push(new_todo) };
    HttpResponse::Created().json(new_todo)
}

// PUT /todos/{id} - update todo by id (only fields provided in body)
pub async fn update_todo(id: web::Path<i32>, todo: web::Json<Todo>) -> HttpResponse {
    let todo = unsafe {
        TODOS.iter_mut()
            .find(|t| t.id == id.into())
            .map(|t| {
                t.title = todo.title.clone();
                t.completed = todo.completed;
                t
            })
    };
    match todo {
        Some(_) => HttpResponse::Ok().json("Todo updated"),
        None => HttpResponse::NotFound().json("Todo not found"),
    }
}

// DELETE /todos/{id} - delete todo by id
pub async fn delete_todo(id: web::Path<i32>) -> HttpResponse {
    let todo = unsafe {
        TODOS.iter().find(|t| t.id == id.into())
            .map(|t| {
                TODOS.retain(|todo| todo.id != id.into());
                true
            })
    };
    match todo {
        Some(_) => HttpResponse::NoContent().finish(),
        None => HttpResponse::NotFound().json("Todo not found"),
    }
}

