export const route = {
  GET: async (req, res) => {
    const todos = await req.db('todos').select();
    return res.json(todos);
  },

  GET: async (req, res) => {
    const { id } = req.params;
    const todo = await req.db('todos').where('id', id).first();
    if (!todo) {
      return res.status(404).json({ error: 'Todo not found' });
    }
    return res.json(todo);
  },

  POST: async (req, res) => {
    const { title } = req.body;
    if (!title) {
      return res.status(400).json({ error: 'Title is required' });
    }
    const todo = await req.db('todos').insert({
      title,
      completed: false,
    });
    return res.status(201).json(todo);
  },

  PUT: async (req, res) => {
    const { id } = req.params;
    const { title, completed } = req.body;

    // Validate required fields
    if (!title && !completed) {
      return res.status(400).json({ error: 'At least one field (title or completed) is required' });
    }

    const todo = await req.db('todos')
      .where('id', id)
      .update({ title, completed })
      .returning('*');

    if (!todo.length) {
      return res.status(404).json({ error: 'Todo not found' });
    }
    return res.json(todo[0]);
  },

  DELETE: async (req, res) => {
    const { id } = req.params;
    const result = await req.db('todos').where('id', id).delete();
    if (!result) {
      return res.status(404).json({ error: 'Todo not found' });
    }
    return res.status(204).end();
  }
};

