use actix_web::{web, HttpResponse, HttpMessage};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;

#[derive(Serialize, Deserialize, Debug)]
pub struct Todo {
    pub id: i32,
    pub title: String,
    pub completed: bool,
}

// In-memory storage for todos (in a real app, this would be replaced with a database)
lazy_static::lazy_static! {
    pub static ref TODOS: std::sync::Mutex<HashMap<i32, Todo>> = std::sync::Mutex::new(HashMap::new());
}

// GET /todos - list all todos
pub async fn list_todos() -> HttpResponse {
    let todos = TODOS.lock().unwrap().values().cloned().collect::<Vec<_>>();
    HttpResponse::Ok().json(todos)
}

// GET /todos/{id} - get todo by id
pub async fn get_todo(id: web::Path<i32>) -> HttpResponse {
    let todo = TODOS.lock().unwrap().get(&id).cloned();
    match todo {
        Some(todo) => HttpResponse::Ok().json(todo),
        None => HttpResponse::NotFound().json("Todo not found"),
    }
}

// POST /todos - create a new todo
pub async fn create_todo(todo: web::Json<Todo>) -> HttpResponse {
    let mut todos = TODOS.lock().unwrap();
    let new_id = todos.keys().max().map_or(0, |k| k + 1);
    let todo_with_id = Todo {
        id: new_id,
        ..todo
    };
    todos.insert(new_id, todo_with_id);
    HttpResponse::Created().json(todo_with_id)
}

// PUT /todos/{id} - update a todo by id
pub async fn update_todo(
    id: web::Path<i32>,
    todo: web::Json<Todo>,
) -> HttpResponse {
    let mut todos = TODOS.lock().unwrap();
    if let Some(_) = todos.get_mut(&id) {
        // Only update fields present in the request body
        if let Some(title) = todo.title.as_str() {
            if !title.is_empty() {
                todos.get_mut(&id).unwrap().title = todo.title.clone();
            }
        }
        if let Some(completed) = todo.completed {
            todos.get_mut(&id).unwrap().completed = completed;
        }
        HttpResponse::Ok().json(todo)
    } else {
        HttpResponse::NotFound().json("Todo not found")
    }
}

// DELETE /todos/{id} - delete a todo by id
pub async fn delete_todo(id: web_::Path<i32>) -> HttpResponse {
    let mut todos = TODOS.lock().unwrap();
    if todos.remove(&id).is_some() {
        HttpResponse::NoContent().finish()
    } else {
        HttpResponse::NotFound().json("Todo not found")
    }
}

// Route handlers
pub fn routes() -> Vec<actix_web::web::Route> {
    vec![
        web::scope("/todos")
            .route("", web::get().to(list_todos))
            .route("", web::post().to(create_todo))
            .route("{id}", web::get().to(get_todo))
            .route("{id}", web::put().to(update_todo))
            .route("{id}", web::delete().to(delete_todo)),
    ]
}

