use axum::{
    http::StatusCode,
    routing::{get, post, put, delete},
    Json, Router,
};
use serde::{Deserialize, Serialize};
use std::sync::Arc;

#[derive(Debug, Serialize, Deserialize)]
pub struct Todo {
    pub id: i32,
    pub title: String,
    pub completed: bool,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct TodoCreate {
    pub title: String,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct TodoUpdate {
    pub title: Option<String>,
    pub completed: Option<bool>,
}

// In-memory storage (in a real app, this would be replaced with a database)
pub struct TodoService {
    todos: Arc<std::sync::Mutex<Vec<Todo>>>,
}

impl TodoService {
    pub fn new() -> Self {
        Self {
            todos: Arc::new(std::sync::Mutex::new(vec![])),
        }
    }

    pub async fn list_todos(&self) -> Vec<Todo> {
        self.todos.lock().await.to_vec()
    }

    pub async fn get_todo(&self, id: i32) -> Option<Todo> {
        let todos = self.todos.lock().await;
        todos.iter().find(|todo| todo.id == id).cloned()
    }

    pub async fn create_todo(&self, todo: TodoCreate) -> Result<Todo, &'static str> {
        if todo.title.is_empty() {
            return Err("Title cannot be empty");
        }

        let new_todo = Todo {
            id: self.next_id(),
            title: todo.title.clone(),
            completed: false,
        };

        let mut todos = self.todos.lock().await;
        todos.push(new_todo);
        Ok(new_todo)
    }

    pub async fn update_todo(&self, id: i32, updates: TodoUpdate) -> Result<Todo, &'static str> {
        let mut todos = self.todos.lock().await;
        let todo = todos.iter_mut().find(|todo| todo.id == id);

        match todo {
            Some(todo) => {
                if let Some(title) = &updates.title {
                    todo.title = title.clone();
                }
                if let Some(completed) = &updates.completed {
                    todo.completed = *completed;
                }
                Ok(todo.clone())
            }
            None => Err("Todo not found"),
        }
    }

    pub async fn delete_todo(&self, id: i32) -> Result<(), &'static str> {
        let mut todos = self.todos.lock().await;
        todos.retain(|todo| todo.id != id);
        Ok(())
    }

    fn next_id(&self) -> i32 {
        let todos = self.todos.lock().await;
        let max_id = todos.iter().map(|todo| todo.id).max().unwrap_or(0);
        max_id + 1
    }
}

pub fn router(todo_service: Arc<TodoService>) -> Router {
    Router::new()
        .route("/todos", get(list_todos))
        .route("/todos", post(create_todo))
        .route("/todos/:id", get(get_todo))
        .route("/todos/:id", put(update_todo))
        .route("/todos/:id", delete(delete_todo))
}

async fn list_todos(State(todo_service): State<Arc<TodoService>>) -> Json<Vec<Todo>> {
    todo_service.list_todos().await
}

async fn get_todo(
    State(todo_service): State<Arc<TodoService>>,
    Path(id): Path<i32>,
) -> Result<Json<Todo>, StatusCode> {
    todo_service.get_todo(id).await.map(Json).map_err(|_| (StatusCode::NOT_FOUND, ""))
}

async fn create_todo(
    State(todo_service): State<Arc<TodoService>>,
    Json(todo): Json<TodoCreate>,
) -> Result<Json<Todo>, StatusCode> {
    todo_service.create_todo(todo).await.map(Json).map_err(|_| (StatusCode::BAD_REQUEST, ""))
}

async fn update_todo(
    State(todo_service): State<Arc<TodoService>>,
    Path(id): Path<i32>,
    Json(update): Json<TodoUpdate>,
) -> Result<Json<Todo>, StatusCode> {
    todo_service.update_todo(id, update).await.map(Json).map_err(|_| (StatusCode::BAD_REQUEST, ""))
}

async fn delete_todo(
    State(todo_service): State<Arc<TodoService>>,
    Path(id): Path<i32>,
) -> Result<(), StatusCode> {
    todo_service.delete_todo(id).await.map_err(|_| (StatusCode::NOT_FOUND, ""))
}

