use actix_web::{web, HttpResponse, http::StatusCode};
use serde::{Deserialize, Serialize};
use std::sync::Mutex;

#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct Todo {
    pub id: i32,
    pub title: String,
    pub completed: bool,
}

// In-memory storage for todos (in a real app, this would be persisted)
static TODOS: Mutex<Vec<Todo>> = Mutex::new(vec![]);

// GET /todos - list all todos
async fn list_todos() -> HttpResponse {
    let todos = TODOS.lock().unwrap().clone();
    HttpResponse::Ok().json(todos)
}

// GET /todos/{id} - get todo by id
async fn get_todo(id: web::Path<i32>) -> HttpResponse {
    let todos = TODOS.lock().unwrap().clone();
    let todo = todos.into_iter().find(|todo| todo.id == id.into());
    match todo {
        Some(todo) => HttpResponse::Ok().json(todo),
        None => HttpResponse::NotFound().json("Todo not found"),
    }
}

// POST /todos - create a new todo
async fn create_todo(todo: web::Json<Todo>) -> HttpResponse {
    let mut todos = TODOS.lock().unwrap();
    let new_todo = Todo {
        id: todos.len() as i32 + 1,
        title: todo.title.clone(),
        completed: todo.completed,
    };
    todos.push(new_todo);
    HttpResponse::Created().json(new_todo)
}

// PUT /todos/{id} - update a todo by id
async fn update_todo(id: web::Path<i32>, todo: web::Json<Todo>) -> HttpResponse {
    let mut todos = TODOS.lock().unwrap();
    let todo_idx = todos.iter().position(|t| t.id == id.into());
    match todo_idx {
        Some(idx) => {
            todos[idx] = todo.clone();
            HttpResponse::Ok().json(todo),
        }
        None => HttpResponse::NotFound().json("Todo not found"),
    }
}

// DELETE /todos/{id} - delete a todo by id
async fn delete_todo(id: web::Path<i32>) -> HttpResponse {
    let mut todos = TODOS.lock().unwrap();
    let todo_idx = todos.iter().position(|t| t.id == id.into());
    match todo_idx {
        Some(idx) => {
            todos.remove(idx);
            HttpResponse::NoContent().finish(),
        }
        None => HttpResponse::NotFound().json("Todo not found"),
    }
}

// Route definitions
pub fn config(cfg: &mut web::ServiceConfig) {
    cfg.route("/todos", web::get().to(list_todos));
    cfg.route("/todos/{id}", web::get().to(get_todo));
    cfg.route("/todos", web::post().to(create_todo));
    cfg.route("/todos/{id}", web::put().to(update_todo));
    cfg.route("/todos/{id}", web::delete().to(delete_todo));
}

