package todo

import (
	"encoding/json"
	"net/http"
	"strconv"
	"strings"

	"github.com/gorilla/mux"
)

// Todo represents a todo item with a title and completed status
type Todo struct {
	ID       int    `json:"id"`
	Title    string `json:"title"`
	Completed bool  `json:"completed"`
}

// TodoList represents a list of todos
type TodoList []Todo

// API handles the HTTP endpoints for todo management
type API struct {
	todos TodoList
}

// NewAPI creates a new todo API
func NewAPI() *API {
	return &API{
		todos: make(TodoList, 0),
	}
}

// List handles GET /todos - returns a list of todos
func (a *API) List(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(a.todos)
}

// Get handles GET /todos/{id} - returns a todo by ID
func (a *API) Get(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	id, err := strconv.Atoi(vars["id"])
	if err != nil {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	todo := a.findTodoByID(id)
	if todo == nil {
		http.Error(w, "Todo not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(todo)
}

// Create handles POST /todos - creates a new todo
func (a *API} Create(w http.ResponseWriter, r *http.Request) {
	var todo Todo
	if err := json.NewDecoder(r.Body).Decode(&todo); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	if todo.Title == "" {
		http.Error(w, "Title is required", http.StatusBadRequest)
		return
	}

	todo.ID = len(a.todos) + 1
	a.todos = append(a.todos, todo)

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(todo)
}

// Update handles PUT /todos/{id} - updates a todo by ID
func (a *API) Update(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	id, err := strconv.Atoi(vars["id"])
	if err != nil {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	var todo Todo
	if err := json.NewDecoder(r.Body).Decode(&todo); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	if todo.Title == "" {
		http.Error(w, "Title is required", http.StatusBadRequest)
		return
	}

	// Update only the fields present in the request body
	for i, t := range a.todos {
		if t.ID == id {
			a.todos[i].Title = todo.Title
			a.todos[i].Completed = todo.Completed
			break
		}
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(todo)
}

// Delete handles DELETE /todos/{id} - deletes a todo by ID
func (a *API) Delete(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	id, err := strconv.Atoi(vars["id"])
	if err != nil {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	for i, todo := range a.todos {
		if todo.ID == id {
			a.todos = append(a.todos[:i], a.todos[i+1:]...)
			return
		}
	}

	http.Error(w, "Todo not found", http.StatusNotFound)
}

// findTodoByID finds a todo by ID
func (a *API) findTodoByID(id int) *Todo {
	for _, todo := range a.todos {
		if todo.ID == id {
			return &todo
		}
	}
	return nil
}

