use actix_web::{web, HttpResponse, http::header::HeaderValue};
use serde::{Deserialize, Serialize};
use std::sync::Arc;

// Define the Todo struct
#[derive(Debug, Serialize, Deserialize, Clone)]
pub struct Todo {
    pub id: i32,
    pub title: String,
    pub completed: bool,
}

// Define the request body for creating or updating a todo
#[derive(Debug, Serialize, Deserialize, Clone)]
pub struct TodoRequest {
    pub title: String,
    pub completed: Option<bool>,
}

// Define the response structure
#[derive(Debug, Serialize, Deserialize, Clone)]
pub struct TodoResponse {
    pub id: i32,
    pub title: String,
    pub completed: bool,
}

// Todo service with CRUD operations
pub struct TodoService {
    todos: Arc<std::sync::Mutex<Vec<Todo>>>,
}

impl TodoService {
    pub fn new() -> Self {
        Self {
            todos: Arc::new(std::sync::Mutex::new(vec![])),
        }
    }

    pub async fn list_todos(&self) -> HttpResponse {
        let todos = self.todos.lock().unwrap().clone();
        HttpResponse::Ok().json(todos)
    }

    pub async fn get_todo(&self, id: i32) -> HttpResponse {
        let todos = self.todos.lock().unwrap().clone();
        let todo = todos.iter().find(|todo| todo.id == id);
        match todo {
            Some(todo) => HttpResponse::Ok().json(todo.clone()),
            None => HttpResponse::NotFound().json("Todo not found"),
        }
    }

    pub async fn create_todo(&self, request: TodoRequest) -> HttpResponse {
        let mut todos = self.todos.lock().unwrap();
        let new_todo = Todo {
            id: todos.len() as i32 + 1,
            title: request.title.clone(),
            completed: request.completed.unwrap_or(false),
        };
        todos.push(new_todo.clone());
        HttpResponse::Created().json(new_todo)
    }

    pub async fn update_todo(&self, id: i32, request: TodoRequest) -> HttpResponse {
        let mut todos = self.todos.lock().unwrap();
        let todo_index = todos.iter().position(|todo| todo.id == id);
        match todo_index {
            Some(index) => {
                let updated_todo = Todo {
                    id: id,
                    title: request.title.clone(),
                    completed: request.completed.unwrap_or(false),
                };
                todos[index] = updated_todo;
                HttpResponse::Ok().json(updated_todo)
            }
            None => HttpResponse::NotFound().json("Todo not found"),
        }
    }

    pub async fn delete_todo(&self, id: i64) -> HttpResponse {
        let mut todos = self.todos.lock().unwrap();
        let todo_index = todos.iter().position(|todo| todo.id == id as i32);
        match todo_index {
            Some(index) => {
                todos.remove(index);
                HttpResponse::Ok().json("Todo deleted successfully"),
            }
            None => HttpResponse::NotFound().json("Todo not found"),
        }
    }
}

// Routes for Todo resource
pub fn routes() -> Vec<web::Route> {
    vec![
        web::resource("/todos")
            .route(web::get().to(|_| todo_service().list_todos()))
            .route(web::post().to(|request: TodoRequest| todo_service().create_todo(request))),
        web::resource("/todos/{id}")
            .route(web::get().to(|id: web::Path<i32>| todo_service().get_todo(id)))
            .route(web::put().to(|id: web::Path<i32>, request: TodoRequest| todo_service().update_todo(id, request)))
            .route(web::delete().to(|id: web::Path<i32>| todo_service().delete_todo(id))),
    ]
}

// Helper function to get the todo service instance
fn todo_service() -> TodoService {
    TodoService::new()
}

