use actix_web::{web, HttpResponse, http::header::HeaderValue};
use serde::{Deserialize, Serialize};
use std::sync::Arc;
use std::collections::HashMap;

#[derive(Serialize, Deserialize, Debug)]
pub struct Todo {
    pub id: i32,
    pub title: String,
    pub completed: bool,
}

#[derive(Serialize, Deserialize, Debug)]
pub struct TodoList {
    pub todos: Vec<Todo>,
}

// In-memory storage for todos (in a real app, this would be a database)
struct TodoStore {
    todos: HashMap<i32, Todo>,
}

impl TodoStore {
    fn new() -> Self {
        TodoStore {
            todos: HashMap::new(),
        }
    }

    fn list(&self) -> TodoList {
        TodoList {
            todos: self.todos.values().cloned().collect(),
        }
    }

    fn get(&self, id: i32) -> Option<Todo> {
        self.todos.get(&id).cloned()
    }

    fn create(&mut self, todo: Todo) -> Todo {
        let id = todo.id;
        self.todos.insert(id, todo);
        todo
    }

    fn update(&mut self, id: i32, todo: Todo) -> Option<Todo> {
        self.todos.get_mut(&id).map(|t| {
            t.title = todo.title.clone();
            t.completed = todo.completed;
            todo.clone()
        })
    }

    fn delete(&mut self, id: i32) -> bool {
        self.todos.remove(&id).is_some()
    }
}

pub async fn list_todos(
    todo_store: web::Data<Arc<TodoStore>>,
) -> HttpResponse<TodoList> {
    let todos = todo_store.read().list();
    HttpResponse::Ok().json(todos)
}

pub async fn get_todo(
    id: web::Path<i32>,
    todo_store: web::Data<Arc<TodoStore>>,
) -> HttpResponse<Todo> {
    let todo = todo_store.read().get(id.into()).unwrap_or_else(|| {
        return HttpResponse::NotFound().json(Todo {
            id: 0,
            title: String::new(),
            completed: false,
        });
    });
    HttpResponse::Ok().json(todo)
}

pub async fn create_todo(
    todo: web::Json<Todo>,
    todo_store: web::Data<Arc<TodoStore>>,
) -> HttpResponse<Todo> {
    let todo = todo_store.write().create(todo);
    HttpResponse::Created().json(todo)
}

pub async fn update_todo(
    id: web::Path<i32>,
    todo: web::Json<Todo>,
    todo_store: web::Data<Arc<TodoStore>>,
) -> HttpResponse<Todo> {
    let todo = todo_store.write().update(id.into(), todo).unwrap_or_else(|| {
        return HttpResponse::BadRequest().json(Todo {
            id: 0,
            title: String::new(),
            completed: false,
        });
    });
    HttpResponse::Ok().json(todo)
}

