static mut TODOS: Option<Vec<Todo>> = None;
static mut TODOS_LOCK: Mutex<()> = Mutex::new(());

// Initialize the todos list
fn init_todos() {
    if let Some(ref mut todos) = unsafe { TODOS.as_mut() } {
        *todos = vec![];
    } else {
        unsafe {
            TODOS = Some(vec![]);
        }
    }
}

// Get all todos
async fn list_todos() -> HttpResponse {
    init_todos();
    let todos = unsafe { TODOS.as_ref().unwrap() }.to_vec();
    HttpResponse::Ok().json(todos)
}

// Get a todo by ID
async fn get_todo(id: web::Path<i32>) -> HttpResponse {
    init_todos();
    let todos = unsafe { TODOS.as_ref().unwrap() };
    let todo = todos.iter().find(|todo| todo.id == id.into()).cloned();
    match todo {
        Some(todo) => HttpResponse::Ok().json(todo),
        None => HttpResponse::NotFound().json("Todo not found"),
    }
}

