use axum::{
    http::StatusCode,
    routing::{get, post, put, delete},
    Json, Router,
};
use serde::{Deserialize, Serialize};
use std::sync::Arc;
use tokio::sync::RwLock;

// Define the Todo struct
#[derive(Serialize, Deserialize, Debug, Clone)]
pub struct Todo {
    pub id: i32,
    pub title: String,
    pub completed: bool,
}

// Define request/response types
#[derive(Serialize, Deserialize)]
pub struct CreateTodoRequest {
    pub title: String,
}

#[derive(Serialize, Deserialize)]
pub struct UpdateTodoRequest {
    pub title: Option<String>,
    pub completed: Option<bool>,
}

// In-memory storage (in a real app, this would be a database)
struct TodoStore {
    todos: Arc<RwLock<Vec<Todo>>>,
}

impl TodoStore {
    fn new() -> Self {
        Self {
            todos: Arc::new(RwLock::new(Vec::new())),
        }
    }

    pub fn list(&self) -> Vec<Todo> {
        self.todos.read().clone()
    }

    pub fn get(&self, id: i32) -> Option<Todo> {
        self.todos.read().iter().find(|todo| todo.id == id).cloned()
    }

    pub fn create(&mut self, todo: Todo) -> Todo {
        todo.id = self.next_id();
        self.todos.write().push(todo);
        todo
    }

    pub fn update(&mut self, id: i32, updates: UpdateTodoRequest) -> Option<Todo> {
        let mut todos = self.todos.write().mutate();
        let todo = todos.iter_mut().find(|todo| todo.id == id)?;
        if let Some(title) = updates.title {
            todo.title = title;
        }
        if let Some(completed) = updates.completed {
            todo.completed = completed;
        }
        Some(todo.clone())
    }

    pub fn delete(&mut self, id: i32) -> Option<Todo> {
        let mut todos = self.todos.write().mutate();
        todos.retain(|todo| todo.id != id);
        let todo = todos.iter().find(|todo| todo.id == id).cloned();
        todo
    }

    fn next_id(&self) -> i32 {
        let todos: Vec<_> = self.todos.read().iter().map(|t| t.id).collect();
        todos.iter().max().map(|id| id + 1).unwrap_or(1)
    }
}

// API routes
pub fn router(todo_store: TodoStore) -> Router {
    Router::new()
        .route("/todos", get(list_todos))
        .route("/todos/:id", get(get_todo))
        .route("/todos", post(create_todo))
        .route("/todos/:id", put(update_todo))
        .route("/todos/:id", delete(delete_todo))
}

// Handlers
async fn list_todos(
    State(todo_store): State<Arc<TodoStore>>,
) -> Json<Vec<Todo>> {
    Json(todo_store.list())
}

async fn get_todo(
    Path(id): Path<i32>,
    State(todo_store): State<Arc<TodoStore>>,
) -> Result<Json<Todo>, StatusCode> {
    todo_store
        .get(id)
        .map(Json)
        .ok_or_else(|| StatusCode::NOT_FOUND)
}

async fn create_todo(
    Json(request): Json<CreateTodoRequest>,
    State(todo_store): State<Arc<TodoStore>>,
) -> Result<Json<Todo>, StatusCode> {
    let todo = Todo {
        id: todo_store.next_id(),
        title: request.title.clone(),
        completed: false,
    };
    let todo = todo_store.create(todo);
    Ok(Json(todo))
}

async fn update_todo(
    Path(id): Path<i32>,
    Json(request): Json<UpdateTodoRequest>,
    State(todo_store): State<Arc<TodoStore>>,
) -> Result<Json<Todo>, StatusCode> {
    let todo = todo_store
        .update(id, request)
        .ok_or_else(|| StatusCode::NOT_FOUND)?;
    Ok(Json(todo))
}

async fn delete_todo(
    Path(id): Path<i32>,
    State(todo_store): State<Arc<TodoStore>>,
) -> Result<StatusCode, StatusCode> {
    todo_store.delete(id);
    Ok(StatusCode::NO_CONTENT)
}

