pub struct TodoUpdate {
    pub title: Option<String>,
    pub completed: Option<bool>,
}

// In-memory storage for todos (in a real app, this would be a database)
struct TodoStore {
    todos: HashMap<i32, Todo>,
}

impl TodoStore {
    fn new() -> Self {
        TodoStore {
            todos: HashMap::new(),
        }
    }

    fn list(&self) -> Vec<Todo> {
        let mut todos: Vec<Todo> = Vec::new();
        for (_, todo) in &self.todos {
            todos.push(todo.clone());
        }
        todos
    }

    fn get(&self, id: i32) -> Option<Todo> {
        self.todos.get(&id).cloned()
    }

    fn create(&mut self, todo: Todo) -> Todo {
        let id = todo.id;
        if self.todos.contains_key(&id) {
            // If ID already exists, just update it (for update, we'd use PUT)
            self.todos.insert(id, todo.clone());
        } else {
            // Otherwise, assign a new ID
            todo.id = id;
            self.todos.insert(id, todo.clone());
        }
        todo
    }

    fn update(&mut self, id: i32, update: TodoUpdate) -> Option<Todo> {
        let todo = self.todos.get(&id).cloned()?;
        let mut updated = todo.clone();
        if let Some(title) = update.title {
            updated.title = title;
        }
        if let Some(completed) = update.completed {
            updated.completed = completed;
        }
        self.todos.insert(id, updated.clone());
        Some(updated)
    }

    fn delete(&mut self, id: i32) -> bool {
        self.todos.remove(&id).is_some()
    }
}

