use actix_web::{web, HttpResponse, HttpServer, Responder};
use serde::{Deserialize, Serialize};
use std::sync::Mutex;

#[derive(Serialize, Deserialize, Debug)]
struct Todo {
    id: i32,
    title: String,
    completed: bool,
}

#[derive(Serialize, Deserialize, Debug)]
struct TodoList {
    todos: Vec<Todo>,
}

// In-memory storage for todos (in a real app, this would be persisted)
static mut TODOS: Option<Mutex<Vec<Todo>>> = None;

fn init_todos() {
    if let Some(todos) = unsafe { &mut TODOS } {
        *todos = Mutex::new(vec![
            Todo {
                id: 1,
                title: "Learn Rust".to_string(),
                completed: false,
            },
            Todo {
                id: 2,
                title: "Build a web app".to_string(),
                completed: true,
            },
        ]);
    }
}

// GET /todos - list all todos
async fn list_todos() -> impl Responder {
    let todos = unsafe { TODOS.as_ref().unwrap().lock().unwrap().clone() };
    HttpResponse::Ok().json(TodoList { todos })
}

// GET /todos/{id} - get todo by id
async fn get_todo(id: web::Path<i32>) -> impl Responder {
    let todos = unsafe { TODOS.as_ref().unwrap().lock().unwrap().clone() };
    let todo = todos
        .iter()
        .find(|todo| todo.id == id.into())
        .cloned()
        .unwrap_or_else(|| {
            HttpResponse::NotFound().json("Todo not found")
        });

    HttpResponse::Ok().json(todo)
}

// POST /todos - create a new todo
async fn create_todo(todo: web::Json<Todo>) -> impl Responder {
    let mut todos = unsafe { TODOS.as_ref().unwrap().lock().unwrap().clone() };
    let new_todo = Todo {
        id: todos.iter().map(|t| t.id).max().unwrap_or(0) + 1,
        title: todo.title.clone(),
        completed: todo.completed,
    };
    todos.push(new_todo);
    unsafe { *TODOS.as_mut().unwrap() = Mutex::new(todos) };
    HttpResponse::Created().json(new_todo)
}

// PUT /todos/{id} - update todo by id
async fn update_todo(
    id: web::Path<i32>,
    todo: web::Json<Todo>,
) -> impl Responder {
    let mut todos = unsafe { TODOS.as_ref().unwrap().lock().unwrap().clone() };
    let updated = todos
        .iter()
        .find(|todo| todo.id == id.into())
        .map(|todo| Todo {
            id: todo.id,
            title: todo.title.clone(),
            completed: todo.completed,
        })
        .unwrap_or_else(|| {
            return HttpResponse::NotFound().json("Todo not found");
        });

    let updated_todo = Todo {
        id: updated.id,
        title: todo.title.clone(),
        completed: todo.completed,
    };

    todos.iter_mut().for_each(|t| {
        if t.id == id.into() {
            t.title = updated_todo.title.clone();
            t.completed = updated_todo.completed;
        }
    });

    unsafe { *TODOS.as_mut().unwrap() = Mutex::new(todos) };
    HttpResponse::Ok().json(updated_todo)
}

// DELETE /todos/{id} - delete todo by id
async fn delete_todo(id: web::Path<i32>) -> impl Responder {
    let mut todos = unsafe { TODOS.as_ref().unwrap().lock().unwrap().clone() };
    todos.retain(|todo| todo.id != id.into());
    unsafe { *TODOS.as_mut().unwrap() = Mutex::new(todos) };
    HttpResponse::NoContent().finish()
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    init_todos();
    HttpServer::new(|| {
        web::scope("/todos")
            .route("/", web::get().to(list_todos))
            .route("/{}", web::get().to(get_todo))
            .route("/", web::post().to(create_todo))
            .route("/{}", web::put().to(update_todo))
            .route("/{}", web::delete().to(delete_todo))
    })
    .bind("127.0.0.1:8080")?
    .run()
    .await
}

