package main

import (
	"encoding/json"
	"net/http"
	"strconv"
)

type Todo struct {
	ID        int  `json:"id"`
	Title     string `json:"title"`
	Completed bool   `json:"completed"`
}

var todos []Todo
var nextID = 1

func main() {
	http.HandleFunc("/todos", handleTodos)
	http.HandleFunc("/todos/", handleTodoByID)
	http.ListenAndServe(":8080", nil)
}

func handleTodos(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case "GET":
		json.NewEncoder(w).Encode(todos)
	case "POST":
		var todo Todo
		if err := json.NewDecoder(r.Body).Decode(&todo); err != nil {
			http.Error(w, "Invalid request body", http.StatusBadRequest)
			return
		}
		todo.ID = nextID
		nextID++
		todos = append(todos, todo)
		json.NewEncoder(w).Encode(todo)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

func handleTodoByID(w http.ResponseWriter, r *http.Request) {
	idStr := r.URL.Path[len("/todos/"):]
	id, err := strconv.Atoi(idStr)
	if err != nil || id < 1 {
		http.Error(w, "Invalid todo ID", http.StatusBadRequest)
		return
	}

	var target *Todo
	for i := range todos {
		if todos[i].ID == id {
			target = &todos[i]
			break
		}
	}

	if target == nil {
		http.Error(w, "Todo not found", http.StatusNotFound)
		return
	}

	switch r.Method {
	case "GET":
		json.NewEncoder(w).Encode(target)
	case "PUT":
		var update map[string]interface{}
		if err := json.NewDecoder(r.Body).Decode(&update); err != nil {
			http.Error(w, "Invalid request body", http.StatusBadRequest)
			return
		}
		if len(update) == 0 {
			http.Error(w, "No attributes provided", http.StatusBadRequest)
			return
		}
		if title, ok := update["title"]; ok {
			target.Title = title.(string)
		}
		if completed, ok := update["completed"]; ok {
			target.Completed = completed.(bool)
		}
		json.NewEncoder(w).Encode(target)
	case "DELETE":
		todos = append(todos[:id-1], todos[id:]...)
		w.WriteHeader(http.StatusNoContent)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

