exports.create = (req, res) => {
  const { title, completed } = req.body;

  if (!title || typeof completed !== 'boolean') {
    return res.status(400).json({ error: 'Title and completed are required' });
  }

  const newTodo = { id: idCounter++, title, completed };
  todos.push(newTodo);
  res.status(201).json(newTodo);
};

exports.show = (req, res) => {
  const todo = todos.find(t => t.id === parseInt(req.params.id));
  if (!todo) return res.status(404).json({ error: 'Todo not found' });
  res.json(todo);
};

exports.update = (req, res) => {
  const { title, completed } = req.body;
  const todoId = parseInt(req.params.id);

  if (Object.keys(req.body).length === 0) {
    return res.status(400).json({ error: 'No data provided' });
  }

  const todoIndex = todos.findIndex(t => t.id === todoId);
  if (todoIndex === -1) return res.status(404).json({ error: 'Todo not found' });

  const updatedTodo = { ...todos[todoIndex] };
  if (title !== undefined) updatedTodo.title = title;
  if (completed !== undefined) updatedTodo.completed = completed;

  todos[todoIndex] = updatedTodo;
  res.json(updatedTodo);
};

exports.destroy = (req, res) => {
  const todoId = parseInt(req.params.id);
  const todoIndex = todos.findIndex(t => t.id === todoId);

  if (todoIndex === -1) return res.status(404).json({ error: 'Todo not found' });

  todos.splice(todoIndex, 1);
  res.status(204).send();
};

