    todos.push(newTodo);
    return newTodo;
  }

  static update(id, data) {
    const todo = todos.find(t => t.id === id);
    if (!todo) return null;
    Object.keys(data).forEach(key => {
      todo[key] = data[key];
    });
    return todo;
  }

  static delete(id) {
    const index = todos.findIndex(t => t.id === id);
    if (index === -1) return false;
    todos.splice(index, 1);
    return true;
  }
}

