class TodosController
  def initialize(todos)
    @todos = todos
  end

  def index
    { todos: @todos.map(&:attributes) }
  end

  def show(id)
    todo = @todos.find { |t| t.id == id }
    todo ? { todo: todo.attributes } : { error: "Todo not found" }, 404
  end

  def create(params)
    todo = Todo.new(id: @todos.map(&:id).max.to_i + 1, title: params[:title], completed: params[:completed] || false)
    @todos << todo
    { todo: todo.attributes }
  end

  def update(id, params)
    todo = @todos.find { |t| t.id == id }
    return { error: "Todo not found" }, 404 unless todo

    todo.title = params[:title] if params.key?(:title)
    todo.completed = params[:completed] if params.key?(:completed)

    { todo: todo.attributes }
  end

  def delete(id)
    @todos.reject! { |t| t.id == id }
    { message: "Todo deleted" }
  end

  private

  def attributes
    { id: @id, title: @title, completed: @completed }
  end
end

