package models

import (
	"sync"
)

var (
	todos = make(map[int]Todo)
	nextID = 1
	mu sync.Mutex
)

func CreateTodo(title string) *Todo {
	mu.Lock()
	defer mu.Unlock()

	todo := &Todo{
		ID:      nextID,
		Title:   title,
		Completed: false,
	}
	todos[nextID] = *todo
	nextID++
	return todo
}

func GetTodo(id int) (*Todo, bool) {
	mu.Lock()
	defer mu.Unlock()

	todo, exists := todos[id]
	return &todo, exists
}

func UpdateTodo(id int, title *string, completed *bool) (*Todo, bool) {
	mu.Lock()
	defer mu.Unlock()

	todo, exists := todos[id]
	if !exists {
		return nil, false
	}

	if title != nil {
		todo.Title = *title
	}
	if completed != nil {
		todo.Completed = *completed
	}

	todos[id] = todo
	return &todo, true
}

func DeleteTodo(id int) bool {
	mu.Lock()
	defer mu.Unlock()

	if _, exists := todos[id]; !exists {
		return false
	}

	delete(todos, id)
	return true
}

func GetAllTodos() []*Todo {
	mu.Lock()
	defer mu.Unlock()

	result := make([]*Todo, 0, len(todos))
	for _, todo := range todos {
		result = append(result, &todo)
	}
	return result
}

