require 'json'

class Todo
  attr_reader :id, :title, :completed

  @@todos = []
  @@next_id = 1

  def initialize(id, title, completed)
    @id = id
    @title = title
    @completed = completed
  end

  def self.all
    @@todos.map { |todo| new(todo.id, todo.title, todo.completed) }
  end

  def self.find(id)
    @@todos.find { |todo| todo.id == id }
  end

  def self.create(attributes)
    raise 'Title is required' unless attributes.key?('title')
    todo = Todo.new(@@next_id, attributes['title'], attributes['completed'] || false)
    @@todos << todo
    @@next_id += 1
    todo
  end

  def self.delete(id)
    @@todos = @@todos.reject { |todo| todo.id == id }
  end

  def update(attributes)
    @title = attributes['title'] if attributes.key?('title')
    @completed = attributes['completed'] if attributes.key?('completed')
  end

  def to_json
    { id: @id, title: @title, completed: @completed }.to_json
  end
end

