		return
	}

	var todo *Todo
	for i := range todos {
		if todos[i].ID == id {
			todo = &todos[i]
			break
		}
	}

	if todo == nil {
		http.Error(w, "Todo not found", http.StatusNotFound)
		return
	}

	switch r.Method {
	case "GET":
		handleGetTodo(w, todo)
